import csv
import io
import re
from typing import Any


def parse_csv(raw_csv: str) -> dict[str, Any]:
    expected_width = 17
    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=";",
        quotechar='"',
        doublequote=True,
        strict=False,
    )

    records = []
    for record in reader:
        if record and any(value.strip() for value in record):
            records.append([value for value in record])

    if not records:
        return {"columns": [], "rows": []}

    def header_score(record: list[str]) -> float:
        populated = [value.strip() for value in record if value.strip()]
        if len(record) < max(2, expected_width - 1) or not populated:
            return -1.0
        textual = sum(
            bool(re.search(r"[A-Za-z]", value))
            and not re.fullmatch(r"[-+]?\d+(?:[.,]\d+)?", value)
            for value in populated
        )
        return textual / len(populated)

    header_index = 0
    for index, record in enumerate(records):
        if header_score(record) >= 0.5:
            header_index = index
            break

    columns = records[header_index][:]
    rows = records[header_index + 1 :]

    width = max(expected_width, len(columns), *(len(row) for row in rows)) if rows else max(expected_width, len(columns))
    columns.extend(f"Column {index + 1}" for index in range(len(columns), width))
    normalized_rows = [row[:width] + [""] * max(0, width - len(row)) for row in rows]

    return {"columns": columns, "rows": normalized_rows}
